"use client";

import { useCallback, useEffect, useState } from "react";
import {
  useAccount,
  useChains,
  useDeployContract,
  useSwitchChain,
  useWaitForTransactionReceipt,
} from "wagmi";
import { type Address, type Hex, isAddress } from "viem";
import toast from "react-hot-toast";
import { chainIdMap } from "@/lib/utils";

// Compiled from ensdomains/durin@f19cd3e, src/examples/L2Registrar.sol, using
// solc 0.8.20, the project's optimizer settings, and EVM London.
const DEFAULT_REGISTRAR_BYTECODE = "" as Hex;

const REGISTRAR_ABI = [
  {
    type: "constructor",
    stateMutability: "nonpayable",
    inputs: [{ name: "_registry", type: "address" }],
  },
] as const;

type Props = {
  registryAddress: string;
  selectedChain: string;
  onDeploySuccess: (address: Address) => void;
  addTransaction: (action: string, chain: string, hash: string) => void;
};

export default function DeployRegistrarButton({
  registryAddress,
  selectedChain,
  onDeploySuccess,
  addTransaction,
}: Props) {
  const [pendingSwitch, setPendingSwitch] = useState(false);
  const { chain, isConnected } = useAccount();
  const chains = useChains();
  const { switchChain, error: switchError } = useSwitchChain();
  const { deployContract, data: hash, error: deployError, isPending } =
    useDeployContract();
  const { data: receipt, isLoading: isConfirming } =
    useWaitForTransactionReceipt({ hash });
  const targetChainId = chainIdMap[selectedChain];

  const deploy = useCallback(() => {
    if (!isConnected) return toast.error("Connect your wallet first");
    if (!isAddress(registryAddress)) {
      return toast.error("Deploy a registry first");
    }
    deployContract({
      abi: REGISTRAR_ABI,
      bytecode: DEFAULT_REGISTRAR_BYTECODE,
      args: [registryAddress],
      chainId: targetChainId,
    });
  }, [deployContract, isConnected, registryAddress, targetChainId]);

  useEffect(() => {
    if (pendingSwitch && chain?.id === targetChainId) {
      setPendingSwitch(false);
      deploy();
    }
  }, [chain?.id, pendingSwitch, targetChainId, deploy]);

  useEffect(() => {
    if (switchError || deployError) {
      setPendingSwitch(false);
      toast.error(
        switchError
          ? "Network switch cancelled"
          : "Registrar deployment rejected"
      );
    }
  }, [switchError, deployError]);

  useEffect(() => {
    if (!receipt?.contractAddress) return;
    onDeploySuccess(receipt.contractAddress);
    addTransaction(
      "Deployed Default Registrar",
      selectedChain,
      receipt.transactionHash
    );
    toast.success("Default registrar deployed");
  }, [receipt, onDeploySuccess, addTransaction, selectedChain]);

  const handleDeploy = () => {
    if (!isAddress(registryAddress)) {
      return toast.error("Deploy a registry first");
    }
    if (chain?.id !== targetChainId) {
      if (!chains.some((item) => item.id === targetChainId)) {
        return toast.error("Selected chain is not configured");
      }
      setPendingSwitch(true);
      switchChain({ chainId: targetChainId });
      return;
    }
    deploy();
  };

  const label = pendingSwitch
    ? "Switching network…"
    : isPending
    ? "Confirm in wallet…"
    : isConfirming
    ? "Deploying…"
    : receipt?.contractAddress
    ? "Registrar deployed ✓"
    : "Deploy default registrar";

  return (
    <button
      onClick={handleDeploy}
      disabled={
        pendingSwitch || isPending || isConfirming || !!receipt?.contractAddress
      }
      className="h-10 px-4 text-sm font-medium border border-stone-900 rounded-lg bg-stone-900 text-white hover:bg-stone-700 disabled:bg-stone-200 disabled:text-stone-500 disabled:border-stone-200 disabled:cursor-not-allowed"
    >
      {label}
    </button>
  );
}
